{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Choose the CT volume",
      "simple": "Select the CT volume to use for planning.",
      "detailed": "This CT provides the bone density information needed for segmentation, 3D reconstruction, and screw planning later in the workflow. Pick the scan that best shows the shoulder and glenoid anatomy."
    },
    {
      "step_id": "cb_step_2",
      "title": "Create the bone segmentation",
      "simple": "In Segment Editor, create a new segmentation named 'Bone_Segmentation'.",
      "detailed": "The segmentation will hold the bone region that is used for the 3D model and surgical planning. Creating a dedicated segmentation keeps the plan organized and gives the thresholding step a clear target to fill."
    },
    {
      "step_id": "cb_step_3",
      "title": "Add the bone segment",
      "simple": "Click 'Add' in Segment Editor and rename the new segment to 'Bone_Segment'.",
      "detailed": "The segment is the container for the voxels that belong to bone. Having a single, clearly named segment makes it easy to confirm which region becomes the final 3D bone model."
    },
    {
      "step_id": "cb_step_4",
      "title": "Open the Threshold effect",
      "simple": "Click the 'Threshold' button in Segment Editor.",
      "detailed": "Thresholding selects CT voxels within a chosen density range, which is how bone is separated from soft tissue and air. Opening the effect gives you the controls to set the correct range in the next step."
    },
    {
      "step_id": "cb_step_5",
      "title": "Set the bone density range",
      "simple": "Adjust the threshold slider so the highlighted region covers the bone of interest.",
      "detailed": "Choose a density range that includes cortical and cancellous bone while excluding soft tissue and air. The preview should clearly outline the glenoid and scapula without including surrounding structures."
    },
    {
      "step_id": "cb_step_6",
      "title": "Apply the threshold",
      "simple": "Click 'Apply' to create the bone segment from the chosen range.",
      "detailed": "Applying the threshold fills the bone segment with all CT voxels in the selected density range. This is the raw bone segmentation that will be cleaned and reconstructed into a 3D model."
    },
    {
      "step_id": "cb_step_7",
      "title": "Open the Islands effect",
      "simple": "Click the 'Islands' button in Segment Editor.",
      "detailed": "Thresholding can leave small disconnected regions around the main bone. The Islands effect removes these artifacts so the final segmentation reflects the actual continuous bone anatomy."
    },
    {
      "step_id": "cb_step_8",
      "title": "Keep the largest bone region",
      "simple": "Choose 'Keep largest island' in the Islands tool.",
      "detailed": "This keeps only the largest connected bone region, normally the scapula and glenoid block, and discards isolated specks. It produces a cleaner bone volume for the 3D reconstruction."
    },
    {
      "step_id": "cb_step_9",
      "title": "Apply the island cleanup",
      "simple": "Click 'Apply' to remove the smaller disconnected regions.",
      "detailed": "Applying the cleanup leaves only the main bone structure. The resulting segmentation is a reliable input for building the 3D model."
    },
    {
      "step_id": "cb_step_10",
      "title": "Select the bone segment",
      "simple": "Select the 'Bone_Segment' segment as the anatomy to reconstruct.",
      "detailed": "This tells the module which segmented region should be converted into a 3D model. Selecting the cleaned bone segment ensures the model matches the relevant surgical anatomy."
    },
    {
      "step_id": "cb_step_11",
      "title": "Build the 3D bone model",
      "simple": "Click '3D Reconstruction' to create the bone model.",
      "detailed": "The reconstruction converts the bone segmentation into a surface model you can inspect and use for planning. This 3D view of the glenoid and scapula is the anatomical base for placing the prosthesis and planning screws."
    },
    {
      "step_id": "cb_step_12",
      "title": "Adjust the 3D view",
      "simple": "Rotate, zoom, and pan the 3D view until the glenoid cavity surface is clearly visible.",
      "detailed": "A clear view of the glenoid cavity is needed to place the prosthesis center precisely. Position the camera so the articular surface is unobstructed and easy to target."
    },
    {
      "step_id": "cb_step_13",
      "title": "Create a point list for the prosthesis center",
      "simple": "In the Markups module, click 'Point List' and name the new list 'Prosthesis_center_point'.",
      "detailed": "This point will store the exact prosthesis center you place on the glenoid surface. Creating an empty point list keeps that location separate from other planning marks."
    },
    {
      "step_id": "cb_step_14",
      "title": "Place the prosthesis center point",
      "simple": "Click on the glenoid cavity surface to place the point.",
      "detailed": "The point marks the planned center of the glenoid component and will be used to align the prosthesis. Place it on the articular surface where you want the component to sit, avoiding loose fragments or the joint rim, then finish the placement."
    },
    {
      "step_id": "cb_step_15",
      "title": "Select the prosthesis center point",
      "simple": "Choose the 'Prosthesis_center_point' list as the planning point.",
      "detailed": "The module needs to know which point represents the prosthesis center. Confirm you select the point you placed on the glenoid so the implant is positioned correctly."
    },
    {
      "step_id": "cb_step_16",
      "title": "Run prosthesis implantation",
      "simple": "Click 'Prosthesis implantation' to place the prosthesis.",
      "detailed": "This step positions the glenoid component at the selected center point on the bone model. You will see the initial prosthesis placement, which you can accept or fine-tune next."
    },
    {
      "step_id": "cb_step_17",
      "title": "Decide whether to adjust the prosthesis",
      "simple": "Choose Yes if the prosthesis needs repositioning, or No to skip adjustment.",
      "detailed": "The initial prosthesis placement is automatic; if it does not sit flush on the glenoid or does not match your intended component position, choose Yes to use the 3D transform handles. If it is already correct, choose No and continue to the plan."
    },
    {
      "step_id": "cb_step_18",
      "title": "Adjust the 3D view",
      "simple": "Rotate, zoom, and pan to inspect the prosthesis from the best angle.",
      "detailed": "A clear view of the prosthesis relative to the glenoid is needed to judge whether the position is acceptable. Move the camera as needed to see the component and the surrounding bone clearly."
    },
    {
      "step_id": "cb_step_19",
      "title": "Update the prosthesis",
      "simple": "Click 'Update Prosthesis' to apply the current prosthesis position.",
      "detailed": "This finalizes the prosthesis placement before the screw plan is calculated. Running it records the current position so the planning step uses the correct implant alignment."
    },
    {
      "step_id": "cb_step_20",
      "title": "Generate the screw plan",
      "simple": "Click 'Plan' to compute the screw planning.",
      "detailed": "This uses the bone model, prosthesis position, and optimization settings to propose screw trajectories for fixation. Review the resulting paths before deciding whether to adjust the screw plan."
    },
    {
      "step_id": "cb_step_21",
      "title": "Decide whether to adjust the screw plan",
      "simple": "Choose Yes to adjust the screw paths, or No to finish.",
      "detailed": "The automatic plan may need fine-tuning to avoid joint surfaces, poor bone, or important surrounding structures. Choose Yes if you want to modify the screw trajectories; otherwise the plan is complete."
    },
    {
      "step_id": "cb_step_22",
      "title": "Adjust the 3D view",
      "simple": "Rotate, zoom, and pan to inspect the screw paths clearly.",
      "detailed": "A clear view of the planned screw paths relative to the bone is needed to judge their safety and position. Adjust the camera to see the trajectories and their endpoints before finalizing the plan."
    },
    {
      "step_id": "cb_step_23",
      "title": "Update the screw plan",
      "simple": "Click 'Update screw' to apply the final screw plan.",
      "detailed": "This applies the current screw trajectories and updates the plan for surgical reference. After this step, the planned fixation paths are ready for review and use."
    }
  ]
}
